const WANTED = ['Clean', 'Solar', 'Wind', 'Gas'];
const MONTH_NAMES = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December'];

const rows = $input.all().map((i) => i.json);
if (rows.length === 0) {
  throw new Error('ember_uk_monthly returned no rows');
}

const months = rows
  .map((r) => r.month)
  .filter((m) => typeof m === 'string' && /^[0-9]{4}-[0-9]{2}$/.test(m))
  .sort();
if (months.length === 0) {
  throw new Error('No valid YYYY-MM month values found in ember_uk_monthly');
}
const latest = months[months.length - 1];
const current = rows.filter((r) => r.month === latest);

const signals = {};
WANTED.forEach((name) => {
  const matches = current.filter((r) => r.series === name);
  if (matches.length !== 1) {
    throw new Error('Expected exactly one ' + name + ' row for ' + latest + ', found ' + matches.length);
  }
  const r = matches[0];
  if (typeof r.share_pct !== 'number' || typeof r.share_change_pts !== 'number') {
    throw new Error(name + ' has a missing or non-numeric share_pct / share_change_pts for ' + latest);
  }
  signals[name] = { share_pct: r.share_pct, share_change_pts: r.share_change_pts };
});

const year = latest.slice(0, 4);
const monthNum = parseInt(latest.slice(5, 7), 10);
const label = MONTH_NAMES[monthNum - 1] + ' ' + year;

const unsigned = (n) => String(n).replace(/^-/, '');
const allowed = [year, String(monthNum), latest.slice(5, 7)];
WANTED.forEach((name) => {
  allowed.push(unsigned(signals[name].share_pct));
  allowed.push(unsigned(signals[name].share_change_pts));
});

return [{
  json: {
    month: latest,
    month_label: label,
    rows_read: rows.length,
    rows_in_month: current.length,
    signals: signals,
    allowed_numbers: allowed
  }
}];

const EXPECTED = ['Solar customer', 'Battery storage prospect', 'EV fleet operator', 'Energy-intensive manufacturer'];
const testMode = $('Run settings').first().json.test_mode === true;

const def = $('Get Segment property definition').first().json;
const options = Array.isArray(def.options) ? def.options : [];
const valueToLabel = {};
EXPECTED.forEach((label) => {
  const opt = options.find((o) => o.label === label && o.hidden !== true);
  if (!opt) {
    throw new Error('HubSpot Segment property has no option labelled "' + label + '"');
  }
  valueToLabel[opt.value] = label;
});

const raw = $input.all().map((i) => i.json);
if (raw.length === 0) {
  throw new Error('HubSpot returned no companies');
}

const skippedBlank = [];
const companies = [];
raw.forEach((c) => {
  const props = c.properties || {};
  const name = props.name && typeof props.name.value === 'string' ? props.name.value : '(no name)';
  const seg = props.segment && typeof props.segment.value === 'string' ? props.segment.value.trim() : '';
  if (c.companyId === undefined || c.companyId === null) {
    throw new Error('Company without an id: ' + name);
  }
  if (seg === '') {
    skippedBlank.push(name);
    return;
  }
  if (!Object.prototype.hasOwnProperty.call(valueToLabel, seg)) {
    throw new Error('Company "' + name + '" has an unrecognised Segment value: "' + seg + '"');
  }
  companies.push({ companyId: String(c.companyId), company_name: name, segment: valueToLabel[seg] });
});
if (companies.length === 0) {
  throw new Error('No companies with a recognised Segment were found');
}

companies.sort((a, b) => (a.companyId.length - b.companyId.length) || a.companyId.localeCompare(b.companyId));

let selected = companies;
if (testMode) {
  const first = companies[0];
  const second = companies.find((c) => c.segment !== first.segment);
  if (!second) {
    throw new Error('Test mode needs companies from two different segments');
  }
  selected = [first, second];
}

return selected.map((c) => ({
  json: Object.assign({}, c, {
    test_mode: testMode,
    companies_fetched: raw.length,
    companies_in_scope: companies.length,
    skipped_blank: skippedBlank
  })
}));

const NL = String.fromCharCode(10);
const GUIDANCE = {
  'Solar customer': 'These customers already generate their own solar power. A lower national solar share says nothing about how much their own panels produce, so do not suggest it does. The angle is that storage lets them shift and store what they generate, so they are less tied to the times when the grid is leaning on other sources. Focus on the Solar figures.',
  'Battery storage prospect': 'These customers are considering batteries. Focus on grid price swings and gas exposure (the Gas figures, plus the Clean and Wind figures if useful) and point to storage for flexibility and arbitrage.',
  'EV fleet operator': 'These customers run electric vehicles. Focus on grid carbon and when charging costs least (the Clean figures, plus Wind or Gas if useful) and point to smart and off-peak charging.',
  'Energy-intensive manufacturer': 'These customers have large energy bills. Focus on the Gas share and price exposure and point to long-term clean supply contracts and demand flexibility.'
};

const sig = $('Pick signals').first().json;
const s = sig.signals;
const fmt = (name) => name + ': share ' + s[name].share_pct + '%, change ' + s[name].share_change_pts + ' percentage points';
const facts = [
  'Month: ' + sig.month_label,
  'Clean share of UK electricity generation: ' + s.Clean.share_pct + '%',
  'Change in Clean share vs previous month: ' + s.Clean.share_change_pts + ' percentage points',
  fmt('Solar'),
  fmt('Wind'),
  fmt('Gas')
].join(NL);

const needed = [];
$input.all().forEach((i) => {
  if (!needed.includes(i.json.segment)) {
    needed.push(i.json.segment);
  }
});

return needed.map((segment) => {
  if (!GUIDANCE[segment]) {
    throw new Error('No guidance defined for segment ' + segment);
  }
  return {
    json: {
      segment: segment,
      prompt: 'Segment: ' + segment + NL + 'Segment guidance: ' + GUIDANCE[segment] + NL + NL + 'Data:' + NL + facts + NL + NL + 'Write the rep note.'
    }
  };
});

const signals = $('Pick signals').first().json;
const briefs = $('Segment briefs').all().map((i) => i.json);
const answers = $input.all().map((i) => i.json);

if (answers.length !== briefs.length) {
  throw new Error('Talking point check failed: expected ' + briefs.length + ' AI answers, got ' + answers.length);
}

const problems = [];
const out = [];
answers.forEach((ai, idx) => {
  const segment = briefs[idx].segment;
  let text = ai.merged_response;
  if (typeof text !== 'string' || text.trim() === '') {
    const parts = Array.isArray(ai.content) ? ai.content : [];
    text = parts.filter((p) => p && p.type === 'text').map((p) => (typeof p.text === 'string' ? p.text : '')).join('');
  }
  if (typeof text !== 'string' || text.trim() === '') {
    problems.push(segment + ': the AI step returned no text');
    return;
  }
  text = text.trim();

  const sentences = text.split(/(?<=[.!?])\s+/).filter((s) => s.trim().length > 0);
  if (sentences.length > 2) {
    problems.push(segment + ': ' + sentences.length + ' sentences, limit is 2');
  }

  const found = text.match(/[0-9]+(?:[.][0-9]+)?/g) || [];
  const unexpected = found.filter((n) => !signals.allowed_numbers.includes(n));
  if (unexpected.length > 0) {
    problems.push(segment + ': numbers not in the supplied figures: ' + unexpected.join(', '));
  }

  out.push({ json: { segment: segment, talking_point: text, sentence_count: sentences.length } });
});

if (problems.length > 0) {
  throw new Error('Talking point check failed: ' + problems.join(' | '));
}
return out;

const NL = String.fromCharCode(10);
const companies = $('Select companies').all().map((i) => i.json);
const points = {};
$input.all().forEach((i) => {
  points[i.json.segment] = i.json.talking_point;
});
const sig = $('Pick signals').first().json;
const dueDays = $('Run settings').first().json.due_in_days;
if (typeof dueDays !== 'number' || dueDays < 0) {
  throw new Error('due_in_days is missing or invalid');
}
const subject = 'Market signal: ' + sig.month_label;
const due = new Date(Date.now() + dueDays * 24 * 60 * 60 * 1000).toISOString();

return companies.map((c) => {
  if (!points[c.segment]) {
    throw new Error('No talking point for segment ' + c.segment + ' (company ' + c.company_name + ')');
  }
  const body = points[c.segment] + NL + NL + 'Source: Ember monthly UK generation data';
  return {
    json: {
      companyId: c.companyId,
      company_name: c.company_name,
      segment: c.segment,
      subject: subject,
      body: body,
      due: due,
      test_mode: c.test_mode
    }
  };
});

const res = $input.first().json;
const ids = [];
(res.results || []).forEach((r) => {
  (r.to || []).forEach((t) => ids.push(String(t.toObjectId)));
});
if (ids.length === 0) {
  return [{ json: { has_tasks: false, ids: [] } }];
}
const chunks = [];
for (let i = 0; i < ids.length; i += 100) {
  chunks.push(ids.slice(i, i + 100));
}
return chunks.map((c) => ({ json: { has_tasks: true, ids: c } }));

const companies = $('Attach talking points').all().map((i) => i.json);
const listRes = $('List tasks on companies').first().json;

(listRes.errors || []).forEach((e) => {
  if (!/NO_ASSOCIATIONS/i.test(JSON.stringify(e))) {
    throw new Error('Task association lookup returned an error: ' + JSON.stringify(e));
  }
});

const byCompany = {};
(listRes.results || []).forEach((r) => {
  byCompany[String(r.from && r.from.id)] = (r.to || []).map((t) => String(t.toObjectId));
});

let readItems = [];
try {
  readItems = $('Read task subjects').all();
} catch (e) {
  readItems = [];
}
const subjectById = {};
readItems.forEach((it) => {
  if (it.json.errors && it.json.errors.length > 0) {
    throw new Error('Reading task subjects returned errors: ' + JSON.stringify(it.json.errors));
  }
  (it.json.results || []).forEach((r) => {
    subjectById[String(r.id)] = r.properties ? r.properties.hs_task_subject : undefined;
  });
});

return companies.map((c) => {
  const ids = byCompany[c.companyId] || [];
  ids.forEach((id) => {
    if (!Object.prototype.hasOwnProperty.call(subjectById, id)) {
      throw new Error('Task ' + id + ' on ' + c.company_name + ' could not be read, so duplicates cannot be ruled out');
    }
  });
  const existing = ids.filter((id) => subjectById[id] === c.subject);
  const payload = {
    properties: {
      hs_task_subject: c.subject,
      hs_task_body: c.body,
      hs_timestamp: c.due,
      hs_task_status: 'NOT_STARTED',
      hs_task_type: 'TODO'
    },
    associations: [
      {
        to: { id: c.companyId },
        types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 192 }]
      }
    ]
  };
  return {
    json: Object.assign({}, c, {
      needs_task: existing.length === 0,
      existing_task_ids: existing,
      tasks_on_company: ids.length,
      task_payload: payload
    })
  };
});

const decisions = $('Decide who needs a task').all().map((i) => i.json);
let created = [];
try {
  created = $('Create HubSpot task').all().map((i) => i.json);
} catch (e) {
  created = [];
}
const need = decisions.filter((d) => d.needs_task);
if (created.length !== need.length) {
  throw new Error('Created ' + created.length + ' tasks but expected ' + need.length);
}
const createdOut = need.map((d, idx) => {
  if (!created[idx] || !created[idx].id) {
    throw new Error('Task create for ' + d.company_name + ' returned no id');
  }
  return { company: d.company_name, segment: d.segment, task_id: String(created[idx].id), subject: d.subject, due: d.due };
});
const sel = $('Select companies').first().json;
const points = {};
decisions.forEach((d) => { points[d.segment] = d.body; });

return [{
  json: {
    test_mode: sel.test_mode,
    month_subject: decisions.length > 0 ? decisions[0].subject : null,
    companies_fetched: sel.companies_fetched,
    companies_in_scope: sel.companies_in_scope,
    skipped_blank_segment: sel.skipped_blank,
    companies_processed: decisions.length,
    tasks_created: createdOut.length,
    created: createdOut,
    skipped_existing: decisions.filter((d) => !d.needs_task).map((d) => ({ company: d.company_name, segment: d.segment, existing_task_ids: d.existing_task_ids })),
    bodies_by_segment: points
  }
}];
